details.returned_prompt:
{
  "high_level_description": "A documentary travel photograph of a hiker's weathered hands holding a folded paper tide table and a yellow pencil on a wet sandstone rock, with receding tidal water and a distant headland behind, shot on iPhone with fine Kodak Portra grain.",
  "compositional_deconstruction": {
    "background": "A late-afternoon tidal flat under a soft pale sky with neutral cool-toned white balance. Wet sand stretches across the midground, sheeting back with a thin reflective film of receding water that catches the sky as a mirror band. A low headland silhouette sits in the upper third of the frame at the far distance. Ambient natural light from a low sun behind camera-right rakes across the scene. Fine Kodak Portra grain runs evenly across the frame.",
    "elements": [
      {
        "type": "obj",
        "desc": "Distant low headland silhouette in the far background, sitting in the upper third of the frame slightly left of center. Dark muted blue-grey shape against the pale sky, flat-topped and softly blurred by atmospheric haze."
      },
      {
        "type": "obj",
        "desc": "Lone seabird gliding low over the water in the far background, small dark silhouette with wings spread horizontally, positioned to the right of the headland near the horizon line."
      },
      {
        "type": "obj",
        "desc": "Dark wet sandstone rock beneath the hands, occupying the lower-center of the frame. Slick surface glistening with seawater, scattered with tiny pale barnacles clustered along one edge and a single stranded limpet shell resting on top, conical and ridged."
      },
      {
        "type": "obj",
        "desc": "Folded paper tide table held open between two weathered hands, anchored slightly right of center. Cream-colored paper with visible grid columns of printed tide data, handwritten pencil marks in the margins, edges softened and slightly creased from handling. Low sun rakes across the page from camera-right."
      },
      {
        "type": "obj",
        "desc": "Weathered hands of a hiker holding the tide table open, fingers slightly sandy with faint grit on the knuckles. Left hand supports the lower edge of the paper; right thumb pins the page open. Skin has natural detailed texture with visible veins and small creases, medium skin tone, raking light catching the knuckles from camera-right."
      },
      {
        "type": "obj",
        "desc": "Yellow wooden pencil with chewed pink eraser end, held between the index and middle finger of the right hand. Sharpened graphite tip angled downward toward a row on the tide table, body gripped firmly, slight wear marks along the yellow paint."
      },
      {
        "type": "obj",
        "desc": "Out-of-focus foreground edge of a canvas daypack strap slicing diagonally in from the lower-left corner. Olive-green canvas webbing with a metal buckle partially visible, heavily blurred by shallow depth of field."
      }
    ]
  }
}
